SELECT COUNT(*) FROM (
    SELECT 1 AS C FROM ${table}
     WHERE ${idCol} = #{bizId}
       AND (${reqCol} = #{userId} OR ${chargerCol} = #{userId})
    UNION ALL
    SELECT 1 FROM OPS_APPR_LINE
     WHERE BIZ_TYPE = #{bizType} AND BIZ_ID = #{bizId} AND ASSIGNEE_ID = #{userId}
    UNION ALL
    SELECT 1 FROM OPS_SHARE
     WHERE BIZ_TYPE = #{bizType} AND BIZ_ID = #{bizId} AND USER_ID = #{userId}
) T

mapper.update:
UPDATE OPS_SHARE
   SET READ_AT = 'Y'
 WHERE BIZ_TYPE = #{bizType}
   AND BIZ_ID = #{bizId}
   AND USER_ID = #{userId}
   AND READ_AT = 'N'

UPDATE OPS_APPR_TEMPLATE
   SET LINE_TYPE = #{lineType}, STEP_NO = #{stepNo}, MEMO = #{memo}
 WHERE TPL_ID = #{tplId}
